            return r
    return -1

def transform_demo(demo):
    inp = demo['input']
    h = len(inp)
    w = len(inp[0])

    # Find separator row (PWM row that's not in bottom section)
    # Search for PWM row in ~10%-40% of height
    for r in range(int(h*0.1), int(h*0.4)):
        if len(set(inp[r])) == 1:
            # Check if this value appears in rows after
            val = inp[r][0]
            rows_after = inp[r+1:]
            values_after = set(val for row in rows_after for val in row)
            if val not in values_after:
                sep_row = r
                break
    else:
        sep_row = -1

    print(f"sep_row={sep_row}")

    if sep_row == -1:
        return None

    top = inp[:sep_row]
    bottom = inp[sep_row+1:]

    t_h = len(top)
    b_h = len(bottom)

    print(f"top section: {t_h}x{w}, bottom: {b_h}x{w}")

    # Check if we have data to work with
    if t_h == 0 or b_h == 0:
        print("No data sections!")
        return None

    if t_h != b_h:
        if b_h == h - 1 and sep_row > 0:
            # Single-section case (top is PWM header)
            bottom = inp[sep_row+1:]
            t_h = b_h
            top = [inp[r] for r in range(b_h)]  # Use same rows as bottom
        else:
            print("Sections don't match!")
            return None

    # Get bottom and output values
    bv = set()
    for r in range(b_h):
        for c in range(w):
            bv.add(bottom[r][c])

    ov = set()
    for r in range(b_h):
        for c in range(w):
            ov.add(demo['output'][r][c])

    print(f"bv={bv}, ov={ov}, len(ov)={len(ov)}")

    # Deng 1: Uniform transformation (all → single value)
    if len(ov) == 1:
        val = ov.pop()
        print(f"Uniform rule: all → {val}")
        return [[val for _ in range(w)] for _ in range(b_h)]

    # Demo 2: Two-section conditional pattern
    # Build rule from (bottom[r][c], top[r][c]) → output
    rule = {}
    for r in range(b_h):
        for c in range(w):
            b, t = bottom[r][c], top[r][c]
            o = demo['output'][r][c]
            key = (b, t)
            if key not in rule:
                rule[key] = {}
            if o not in rule[key]:
                rule[key][o] = 0
            rule[key][o] += 1

